import fs from "node:fs";
import path from "node:path";
import process from "node:process";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const sources = [
  "js/constants.js",
  "js/amsler-engine.js",
  "js/canvas.js",
  "js/analysis.js",
  "js/report.js",
  "js/mcq-data.js",
  "js/mcq.js",
  "js/state.js",
  "js/ui.js",
  "script.js"
];

function stripModuleSyntax(source) {
  return source
    .replace(/^import\s+[\s\S]*?\s+from\s+["'][^"']+["'];\s*$/gm, "")
    .replace(/^export\s+(?=(const|let|var|function|class)\b)/gm, "");
}

function buildBundle() {
  const body = sources.map((relativePath) => {
    const source = fs.readFileSync(path.join(root, relativePath), "utf8");
    return `  // Source: ${relativePath}\n${stripModuleSyntax(source)
      .split("\n")
      .map((line) => `  ${line}`)
      .join("\n")}`;
  }).join("\n\n");

  return `"use strict";\n// Generated by tools/build-bundle.mjs. Do not edit directly.\n(() => {\n${body}\n})();\n`;
}

const outputPath = path.join(root, "app.bundle.js");
const nextBundle = buildBundle();

if (process.argv.includes("--check")) {
  const currentBundle = fs.readFileSync(outputPath, "utf8");
  if (currentBundle !== nextBundle) {
    console.error("app.bundle.js is out of date. Run npm run build.");
    process.exitCode = 1;
  } else {
    console.log("PASS: app.bundle.js matches modular sources.");
  }
} else {
  fs.writeFileSync(outputPath, nextBundle, "utf8");
  console.log("Built app.bundle.js from modular sources.");
}
